-- Refresh unchanged profile copy and add database knowledge; preserve administrator edits.
begin;
update public.profiles set data=jsonb_set(data,'{headline}','"Estudiante de Ingeniería Informática | Desarrollo de software | Bases de datos y sistemas | Interés en IA y ciberseguridad"'::jsonb) where data->'headline'='"Estudiante de Ingeniería Informática | Programación | Arquitectura de Computadoras | Sistemas | Interés en desarrollo de software y tecnología"'::jsonb;
update public.profiles set data=jsonb_set(data,'{headline_en}','"Computer Engineering student | Software development | Databases and systems | Interested in AI and cybersecurity"'::jsonb) where data->'headline_en'='"Computer Engineering student | Programming, Computer Architecture and Systems | Exploring software development"'::jsonb;
update public.profiles set data=jsonb_set(data,'{bio}','"Estudiante de Ingeniería Informática con conocimientos en programación, bases de datos y sistemas. Me interesa desarrollar software y explorar nuevas aplicaciones de la inteligencia artificial y la ciberseguridad."'::jsonb) where data->'bio'='"Estudiante de Ingeniería Informática con interés en programación, arquitectura de computadoras, sistemas y desarrollo de software."'::jsonb;
update public.profiles set data=jsonb_set(data,'{bio_en}','"Computer Engineering student with knowledge of programming, databases and systems. I am interested in developing software and exploring new applications of artificial intelligence and cybersecurity."'::jsonb) where data->'bio_en'='"Computer Engineering student interested in programming, computer architecture, systems and software development."'::jsonb;
update public.profiles set data=jsonb_set(data,'{about}','"Soy estudiante de Ingeniería Informática en la Facultad de Ingeniería del Ejército. Me interesa entender cómo funcionan los sistemas, resolver problemas y transformar ideas en soluciones mediante el software.\n\nMi formación combina programación, bases de datos y arquitectura de computadoras. A través de proyectos personales y académicos, busco conectar esos conocimientos, enfrentar desafíos técnicos y aprender del trabajo en equipo.\n\nLa inteligencia artificial y la ciberseguridad son áreas que quiero seguir explorando, especialmente por su aplicación al desarrollo de sistemas y por las posibilidades que abren para el futuro.\n\nMi experiencia laboral también me permitió desarrollar comunicación, adaptabilidad y trabajo en equipo. Busco una primera oportunidad en tecnología donde pueda aportar estas habilidades y seguir creciendo profesionalmente."'::jsonb) where data->'about'='"Soy estudiante de Ingeniería Informática con gran interés en el funcionamiento interno de las computadoras, la programación y los sistemas tecnológicos.\n\nActualmente me encuentro desarrollando mis conocimientos en áreas como programación, arquitectura de computadoras y electrónica, buscando siempre comprender cómo funcionan los sistemas desde lo más fundamental hasta su aplicación práctica.\n\nMe interesa participar en proyectos que me permitan seguir aprendiendo, enfrentar desafíos técnicos y trabajar en equipo para desarrollar soluciones tecnológicas.\n\nEstoy abierto a oportunidades de aprendizaje, colaboración y desarrollo profesional en el área de tecnología."'::jsonb;
update public.profiles set data=jsonb_set(data,'{about_en}','"I am a Computer Engineering student at the Facultad de Ingeniería del Ejército. I am interested in understanding how systems work, solving problems and turning ideas into solutions through software.\n\nMy studies combine programming, databases and computer architecture. Through personal and academic projects, I aim to connect this knowledge, tackle technical challenges and learn from working with a team.\n\nArtificial intelligence and cybersecurity are areas I want to explore further, particularly their applications in system development and the possibilities they open up for the future.\n\nMy work experience has also helped me develop communication, adaptability and teamwork. I am seeking my first opportunity in technology, where I can contribute these skills and continue growing professionally."'::jsonb) where data->'about_en'='"I am a Computer Engineering student with a curiosity for how computers work, from the underlying hardware to the software and systems built on top of it.\n\nI am building my knowledge of programming, computer architecture and electronics, connecting fundamental concepts with practical applications.\n\nI am looking to contribute to projects where I can keep learning, solve technical problems and collaborate with a team.\n\nI welcome opportunities to learn, collaborate and grow professionally in technology."'::jsonb;
update public.site_settings set data=jsonb_set(data,'{hero_description}','"Estudiante de Ingeniería Informática con conocimientos en programación, bases de datos y sistemas. Me interesa desarrollar software y explorar nuevas aplicaciones de la inteligencia artificial y la ciberseguridad."'::jsonb) where data->'hero_description'='"Estudiante de Ingeniería Informática con conocimientos en programación, bases de datos y sistemas. Me interesa desarrollar software y explorar nuevas aplicaciones de la inteligencia artificial y la ciberseguridad."'::jsonb;
update public.site_settings set data=jsonb_set(data,'{hero_description_en}','"Computer Engineering student with knowledge of programming, databases and systems. I am interested in developing software and exploring new applications of artificial intelligence and cybersecurity."'::jsonb) where data->'hero_description_en'='"Computer Engineering student exploring programming, computer architecture and systems, with a focus on software development."'::jsonb;
update public.seo_settings set data=jsonb_set(data,'{description}','"Estudiante de Ingeniería Informática con conocimientos en programación, bases de datos y sistemas. Me interesa desarrollar software y explorar nuevas aplicaciones de la inteligencia artificial y la ciberseguridad."'::jsonb) where data->'description'='"Estudiante de Ingeniería Informática con conocimientos en programación, bases de datos y sistemas. Me interesa desarrollar software y explorar nuevas aplicaciones de la inteligencia artificial y la ciberseguridad."'::jsonb;
insert into public.skills(id,data,sort_order,is_visible) select '40000000-0000-4000-8000-000000000001','{"name":"Bases de datos","name_en":"Databases","category":"Computer Science","icon":""}'::jsonb,4,true where not exists(select 1 from public.skills where id='40000000-0000-4000-8000-000000000001' or data->>'name'='Bases de datos') on conflict(id) do nothing;
commit;
